rss.channel:
{{ site.title }} — papers
{{ site_url }}
{{ site.tagline }} (one item per paper)
en
{{ generated_at | rfc822 }}

{% for a in papers %}


  {{ a.title }}
  {{ a.link }}
  {{ site_url }}p/{{ a.slug }}.html
  {{ (a.first_seen_at or a.published_at) | rfc822 }}
  {% for n in a.authors %}{{ n }}
  {% endfor %}
  {% for s in a.set_labels %}{{ s }}
  {% endfor %}
  {{ a.venue }}
  <p><em>{{ a.authors | authors_inline | e }}</em> · {{ a.venue | e }} · Issue No. {{ '%03d' | format(a.issue_number) }}</p>{% if a.note %}<p>{{ a.note | e }}</p>{% endif %}<p>{% if a.abstract %}{{ a.abstract | e }}{% else %}No abstract available.{% endif %}</p>{% if a.doi %}<p><a href="https://doi.org/{{ a.doi }}">DOI</a></p>{% endif %}

{% endfor %}
